+	const hasToolOutput = Object.hasOwn(globals, "toolOutput");
+	const hasFullToolResult =
+		hasToolOutput &&
+		isStructuredObject(globals.toolOutput) &&
+		Object.hasOwn(globals.toolOutput, "structuredContent");
+	const hasToolResponseMetadata = Object.hasOwn(
+		globals,
