    20	/** Shared iframe-side runtime for every Lobu MCP App bundle. */
    21	
    22	type ToolArgs = Record<string, unknown>;
    23	type ViewStateValue = boolean | number | string;
    24	type McpAppViewState = Record<string, ViewStateValue>;
    25	
    26	interface McpAppApi<T> {
    27		/** Server-authored LobuViewV1 from the originating tool result. */
    28		data: T | null;
    29		/** Originating MCP tool name, supplied by the standard host context. */
    30		toolName: string | null;
    31		/** Small restored pagination/disclosure state for this exact result card. */
    32		viewState: McpAppViewState;
    33		setViewState: (key: string, value: ViewStateValue) => void;
    34		/** Ask the host to broker a standard MCP `tools/call`. */
    35		callTool: (name: string, args: ToolArgs) => Promise<void>;
    36		/** Ask the host to open an external URL via `ui/open-link`. */
    37		openLink: (href: string) => Promise<void>;
    38		/** Latest app-initiated tool result; `seq` bumps so effects react to retries. */
    39		lastResult: { isError: boolean; seq: number } | null;
    40		/** True only inside Lobu's same-origin SPA parent, never in an external host. */
    41		allowSpaHostedViews: boolean;
    42	}
