   202		const toolCallName = useRef<string | null>(null);
   203		const snapshotCapability = useRef<string | null>(null);
   204		const snapshotBinding = useRef<string | null>(null);
   205		const viewStateRef = useRef<McpAppViewState>({});
   206		const saveStateTimer = useRef<number | null>(null);
