   483					data,
   484					toolName,
   485					viewState,
   486					setViewState,
   487					callTool,
   488					openLink,
   489					lastResult,
   490					allowSpaHostedViews,
   491				}}
   492			>
   493				{children}
   494			</McpAppContext.Provider>
   495		);
   496	}
